(7249318, 1121059, 58634, '<td valign="top">So much motion and speed. As if running (flying) away from the world and never looking back. Emotional.</td>', 'So much motion and speed. As if running (flying) away from the world and never looking back. Emotional.', '2014-08-08 18:37:34.000000', NULL, 0),
(7249321, 1124223, 58634, '<td valign="top">Would''ve been a cool shot, but had to give it a 5 because it wasn''t in focus. I commend you for entering despite that, though. Long exposures can be a lot of fun!</td>', 'Would''ve been a cool shot, but had to give it a 5 because it wasn''t in focus. I commend you for entering despite that, though. Long exposures can be a lot of fun!', '2014-08-08 18:40:04.000000', NULL, 0),
